    $('#review-material').textContent='Exploring a separate line from the displayed position.';$('#review-rating').textContent='Variation · not analysed';$('#review-evaluation').textContent='';$('#review-explanation').textContent='Original-game ratings do not apply to this line.';$('#review-alternatives').textContent='';$('#review-reply-note').textContent='';for(const id of ['review-best','review-reply','review-practise-mistake'])$('#'+id).disabled=true;
