    const entry=entries[reviewIndex-1];$('#review-rating').textContent=reviewIndex===0?'Starting position':entry?.label||'Not analysed';$('#review-evaluation').textContent=entry?`${evaluation(entry.score)} · completed depth ${entry.depth} · loss ${(entry.loss/100).toFixed(2)}`:'';$('#review-explanation').textContent=entry?entry.explanation:reviewIndex===0?'Choose a move to inspect its evaluation and alternatives.':'Analyse this game to see feedback for every move.';$('#review-alternatives').textContent=entry?'Candidates: '+entry.candidates.map(c=>c.san+' ('+evaluation(c.score)+')').join(' · '):'';$('#review-reply').disabled=!entry?.reply;$('#review-reply').textContent=replyPreview?'Back to played move':'Show opponent’s reply';$('#review-best').disabled=!entry;$('#review-practise-mistake').disabled=!entry||!errors.has(entry.label);$('#review-best').textContent=preview?'Back to played move':'Show suggested move';squareBadge(entry);chart();
