  try{const saved=JSON.parse(localStorage.getItem('chess-club-coach'));if(coaches.some(c=>c.id===saved?.id))selected=saved.id;randomOnVisit=saved?.randomOnVisit===true}catch{}
  const current=()=>coaches.find(c=>c.id===selected);
  function persist(){try{localStorage.setItem('chess-club-coach',JSON.stringify({id:selected,randomOnVisit}))}catch{toast('Coach preference could not be saved in this browser.')}}
  const nav=document.createElement('button');nav.className='nav-button';nav.dataset.view='coaches';nav.textContent='Coaches';nav.onclick=()=>switchView('coaches');$('.main-nav').append(nav);
  const section=document.createElement('section');section.id='view-coaches';section.className='section-view';section.hidden=true;section.innerHTML=`<div class="section-heading"><div><h1>Meet your chess coach.</h1><p>Eight original character coaches with built-in tips. Choose a favourite or let the club surprise you.</p></div></div><div class="feature-toolbar"><button class="primary" id="coach-random">🎲 Random coach</button><label class="coach-checkbox"><input id="coach-random-visits" type="checkbox"> Surprise me each time I visit Coaches</label></div><article class="content-card coach-spotlight"><div id="coach-avatar" class="coach-avatar" aria-hidden="true"></div><div><h2 id="coach-name"></h2><p id="coach-style"></p><p id="coach-greeting"></p><label>Advice about<select id="coach-topic"><option value="specialty">My coach’s favourite topic</option><option value="learn">Learning the pieces</option><option value="tactics">Puzzles and tactics</option><option value="openings">Openings</option><option value="endgames">Endgames</option><option value="defence">King safety</option><option value="knights">Knights</option><option value="review">Reviewing a game</option><option value="confidence">Building confidence</option></select></label><p id="coach-advice" class="coach-advice" role="status"></p><div class="feature-actions"><button class="secondary" id="coach-next-tip">Another tip</button><button class="primary" id="coach-practise">Practise together →</button></div><p>These are fictional guides with written tips, not live coaches or AI chat.</p></div></article><h2>Choose your team</h2><div class="feature-grid" id="coach-roster"></div>`;$('main').insertBefore(section,$('main > footer'));
  const companions=[];
