    const c=current();$('#coach-avatar').textContent=c.icon;$('#coach-name').textContent=c.name;$('#coach-style').textContent=c.style;$('#coach-greeting').textContent=c.hello;$('#coach-advice').textContent=tips[topic()][tipIndex%tips[topic()].length];$('#coach-random-visits').checked=randomOnVisit;
    for(const button of $('#coach-roster').children){button.setAttribute('aria-pressed',String(button.dataset.coach===selected));button.classList.toggle('selected-coach',button.dataset.coach===selected)}
